int tag = 3;

switch (tag)
{
    case 1:
        Console.WriteLine("Montag");
        break;
    case 2:
        Console.WriteLine("Dienstag");
        break;
    case 3:
        Console.WriteLine("Mittwoch");
        break;
    default:
        Console.WriteLine("Anderer Tag");
        break;
}
// Ausgabe: Mittwoch

int note = 1;

switch (note)
{
    case 1:
        Console.WriteLine("Sehr gut");
        // Fehler! Hier fehlt break;
    case 2:
        Console.WriteLine("Gut");
        break;
}

int monat = 4;

switch (monat)
{
    case 1:
    case 3:
    case 5:
    case 7:
    case 8:
    case 10:
    case 12:
        Console.WriteLine("31 Tage");
        break;
    case 4:
    case 6:
    case 9:
    case 11:
        Console.WriteLine("30 Tage");
        break;
    case 2:
        Console.WriteLine("28 oder 29 Tage");
        break;
    default:
        Console.WriteLine("Diesen Monat gibt es nicht!");
        break;
}
// Ausgabe: 30 Tage

Console.Write("Befehl (start/stopp/hilfe): ");
string befehl = Console.ReadLine();

switch (befehl)
{
    case "start":
        Console.WriteLine("Das Spiel beginnt!");
        break;
    case "stopp":
        Console.WriteLine("Spiel beendet.");
        break;
    case "hilfe":
        Console.WriteLine("Tippe start oder stopp.");
        break;
    default:
        Console.WriteLine($"Unbekannter Befehl: {befehl}");
        break;
}
// Eingabe: Start
// Ausgabe: Unbekannter Befehl: Start

int tag = 2;
string name = tag switch
{
    1 => "Montag",
    2 => "Dienstag",
    _ => "Anderer Tag"
};
Console.WriteLine(name);
// Ausgabe: Dienstag

